trainingReferenceNotes=function(){return `<section class="training-reference"><h2>技能学习与职业培养</h2><a class="button-link" href="#characters/learning">按角色查看技能与习得等级 ↗</a>${multiClassTable()}</section>`};

// The map uses existing, structured local data; filters never invent chapter availability.
let atlasRelationCache=new Map(),atlasCacheSource=null;
const MAP_PURPOSES={all:'全部',recruit:'招募',shop:'买东西',gather:'材料',mount:'坐骑',renown:'声望'};
const MAP_TYPE_ICONS={据点:'M4 21V8l8-6 8 6v13H4 M9 21v-7h6v7',小据点:'m3 11 9-8 9 8 M5 10v11h14V10',神殿:'M3 21h18 M4 8h16L12 2Z M6 9v10 M12 9v10 M18 9v10',驿站:'M4 20V5h16v15 M7 12h10 M7 15h10 M7 18v2 M17 18v2',关卡:'M4 21V3 M4 4h15l-3 4 3 4H4',蔬菜:'M5 20C2 6 13 3 21 3c0 12-6 17-16 17 M5 20 16 8',鱼:'M4 12C8 4 16 4 20 12c-4 8-12 8-16 0 M4 12l-3-4v8Z M15 10h.1',矿石:'m3 9 5-6h8l5 6-9 12Z M3 9h18 M8 3l4 18 4-18',道具:'M5 8h14v13H5Z M3 4h18v4H3Z M12 4v17'};
function atlasIcon(type){const path=MAP_TYPE_ICONS[type]||'M12 3a7 7 0 0 0-7 7c0 5 7 11 7 11s7-6 7-11a7 7 0 0 0-7-7Z M12 7v6 M9 10h6';return `<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${path}"/></svg>`}
function atlasRelated(p){if(atlasCacheSource!==MAP_EXTRAS){atlasRelationCache.clear();atlasCacheSource=MAP_EXTRAS}if(atlasRelationCache.has(p.id))return atlasRelationCache.get(p.id);const extras=MAP_EXTRAS||{shops:[],gather:[],mounts:[],renown:[]},name=n=>String(n||'').includes(p.name)||p.name.includes(String(n||''))&&!!n;const out={shops:extras.shops.filter(s=>s.place===p.id),gather:extras.gather.filter(s=>s.place===p.id),mounts:extras.mounts.filter(m=>m.areas.some(name)),recruits:DB.characters.flatMap(c=>c.joinDetails.filter(j=>j.method!=='対象外'&&j.place&&name(zh(j.place))&&(p.area===j.route.replace('編','')||j.route==='共通')).map(j=>({c,j}))),renown:extras.renown.filter(r=>r.areas.some(name))};atlasRelationCache.set(p.id,out);return out}
function atlasMatches(p){if(mapArea!=='all'&&p.area!==mapArea)return false;if(mapType==='none'||mapType!=='all'&&p.type!==mapType)return false;const r=atlasRelated(p);if(mapPurpose==='shop'&&!r.shops.length)return false;if(mapPurpose==='gather'&&!r.gather.length&&!MAP_GATHER_TYPES.includes(p.type))return false;if(mapPurpose==='recruit'&&!r.recruits.length)return false;if(mapPurpose==='mount'&&!r.mounts.length)return false;if(mapPurpose==='renown'&&!r.renown.length)return false;if(!query)return true;const text=[p.name,p.info,p.type,...r.shops.flatMap(s=>s.goods.map(g=>g[0])),...r.gather.map(g=>g.item),...r.recruits.map(x=>x.c.cn),...r.mounts.map(m=>m.name)].join(' ');return materialQueryVariants(query).some(q=>text.includes(q))}
function atlasRoutes(){return `<div class="atlas-routes" aria-label="地图路线">${[...CATALOG.presentation.heroes.map(h=>[h.route,DB.characters.find(c=>c.id===h.id)]),['all',null]].map(([r,c])=>`<button data-map-area="${r}" aria-pressed="${mapArea===r}" class="${mapArea===r?'active':''}">${c?portrait(c):`<span class="atlas-union">${atlasIcon('据点')}</span>`}<span>${c?esc(c.cn):'全路线'}</span></button>`).join('')}</div>`}
mapPage=function(){if(!mapLoaded){loadMap();return title('地图','探索大地图','')+loadingBlock('正在载入地图…',{rows:4})}if(!MAP_EXTRAS)loadMapExtras();const raw=PINS.filter(atlasMatches),list=mapArea==='all'?uniquePins(raw):raw,types=[...new Set(PINS.map(p=>p.type))];return `<section class="map-stage atlas-stage" data-skill-images="off"><aside class="map-panel atlas-panel" aria-label="地图筛选与地点"><div class="map-panel-head"><h1>探索大地图</h1><span>${list.length} 个地点</span></div>${atlasRoutes()}<div class="atlas-purposes" aria-label="探索目的">${Object.entries(MAP_PURPOSES).map(([k,n])=>`<button data-map-purpose="${k}" aria-pressed="${mapPurpose===k}" class="${mapPurpose===k?'active':''}">${n}</button>`).join('')}</div>${toolbar('搜地点、商品、材料、角色…')}<details class="atlas-layers"><summary>显示地点类型 <span>${mapType==='all'?'全部':mapType==='none'?'已隐藏':esc(mapType)}</span></summary><div class="atlas-layer-actions"><button data-maptype="all">全显示</button><button data-maptype="none">全隐藏</button></div><div class="atlas-layer-grid">${types.map(t=>`<button data-maptype="${esc(t)}" aria-pressed="${mapType==='all'||mapType===t}" class="${mapType==='all'||mapType===t?'active':''}">${atlasIcon(t)}${esc(t)}</button>`).join('')}</div></details><div id="map-pin-detail" class="map-pin-detail" aria-live="polite">${mapSelected?mapPinDetail(mapSelected):''}</div><div class="map-results"><h3>${query?'搜索结果':'地点索引'}</h3>${list.map(p=>`<button class="map-result ${p.id===mapSelected?'selected':''}" data-pin="${p.id}">${atlasIcon(p.type)}<span><b>${esc(p.name)}</b><small>${esc(p.type)} · ${esc(routes[p.area]||p.area)}</small></span></button>`).join('')||'<p class="muted">没有匹配地点，请调整路线、类型或关键词。</p>'}</div></aside><div class="map-main"><div class="atlas-map-caption">世界地图 <span>${mapArea==='all'?'全路线':esc(routes[mapArea])}</span></div><div class="map-viewport" tabindex="0" aria-label="地图：单指拖动、双指缩放，键盘方向键平移，加减号缩放"><div class="map-canvas"><img class="world-map" src="world-map.webp" alt="中文世界地图" decoding="async" draggable="false"><div class="map-tiles"></div><div class="map-pins">${list.map(p=>`<button class="pin atlas-pin ${MAP_GATHER_TYPES.includes(p.type)?'gather-pin':'shop-pin'} ${p.id===mapSelected?'selected':''}" style="left:${p.x}%;top:${p.y}%" data-place-type="${escapeAttr(p.type)}" data-pin="${p.id}" title="${esc(p.name+' · '+p.type)}" aria-label="${esc(p.name+' · '+p.type)}">${atlasIcon(p.type)}${query||['据点','小据点','神殿','驿站'].includes(p.type)||p.id===mapSelected?`<span class="pin-label ${query?'searched-label':''}">${esc(p.name)}</span>`:''}</button>`).join('')}</div></div></div><div class="map-zoom-controls" role="group" aria-label="地图缩放"><button data-zoom="1" aria-label="放大">＋</button><button data-zoom="-1" aria-label="缩小">−</button><button data-zoom="0" aria-label="复位地图">复位</button><button data-atlas-fullscreen aria-label="全屏地图"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M8 3H3v5 M16 3h5v5 M21 16v5h-5 M8 21H3v-5"/></svg></button></div></div></section>${atlasRenownTable()}`};
function atlasRenownTable(){if(!MAP_EXTRAS)return '';return `<section class="atlas-renown" data-skill-images="off"><h2>声望解锁速查</h2><div class="table-wrap"><table><thead><tr><th>声望</th><th>设施与功能</th><th>解锁地点</th><th>相关委托</th></tr></thead><tbody>${MAP_EXTRAS.renown.map(r=>`<tr><th scope="row">Lv.${r.lv}</th><td>${esc(r.text)}${r.routes.map(x=>`<small>${esc(typeof x==='string'?x:(routes[x.route?.replace('編','')]||x.route)+' · '+x.text)}</small>`).join('')}</td><td>${r.areas.map(n=>`<button class="text-button" data-atlas-find="${escapeAttr(n)}">${esc(n)}</button>`).join('、')||'—'}</td><td>${r.quests.map(q=>esc(typeof q==='string'?q:q.name)).join('、')||'—'}</td></tr>`).join('')}</tbody></table></div></section>`}
const atlasBaseDetail=mapPinDetail;
mapPinDetail=function(id){
 const p=PINS.find(p=>p.id===id);let html=atlasBaseDetail(id);if(!p)return html;
 const r=atlasRelated(p);let extra='';
 if(r.recruits.length)extra+='<h3>可在此招募</h3>'+r.recruits.map(({c,j})=>`<div class="atlas-recruit">${tableCharacter(c,{showRating:false,subtitle:[j.chapter,j.renown?'声望 '+j.renown:'',j.method].filter(Boolean).join(' · ')})}</div>`).join('');
 if(r.mounts.length)extra+='<h3>坐骑</h3>'+r.mounts.map(m=>`<p><b>${esc(m.name)}</b> · ${esc(m.obtain)}<small>偏好食物：${esc(m.food)}</small></p>`).join('');
 if(r.renown.length)extra+='<h3>声望条件</h3>'+r.renown.map(r=>`<p>声望 Lv.${r.lv} 解锁</p>`).join('');
 return html.replace('<a class="map-pin-source"',extra+'<a class="map-pin-source"');
};
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-learning-kind],[data-map-purpose],[data-atlas-find],[data-atlas-fullscreen]');if(!b)return;if(b.dataset.learningKind){rosterLearningKind=b.dataset.learningKind;rosterLearningSkill='all';render()}if(b.dataset.mapPurpose){mapPurpose=b.dataset.mapPurpose;mapSelected=null;render()}if(b.dataset.atlasFind){query=b.dataset.atlasFind;mapArea='all';mapType='all';mapPurpose='all';render();document.querySelector('.atlas-stage')?.scrollIntoView({behavior:'smooth'})}if(b.hasAttribute('data-atlas-fullscreen')){const stage=document.querySelector('.atlas-stage');if(document.fullscreenElement)document.exitFullscreen?.();else stage?.requestFullscreen?.().catch(()=>toast('当前浏览器不支持全屏地图'))}});
document.addEventListener('keydown',e=>{if(!e.target.matches?.('.atlas-stage .map-viewport')||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();if(e.key==='ArrowLeft')mapX+=60;if(e.key==='ArrowRight')mapX-=60;if(e.key==='ArrowUp')mapY+=60;if(e.key==='ArrowDown')mapY-=60;clampMap();scheduleMap()});

loadMapExtras=function(){if(mapExtrasLoading||MAP_EXTRAS)return;mapExtrasLoading=true;fetch('map-extras.json?v=1').then(r=>{if(!r.ok&&r.ok!==undefined)throw Error();return r.json()}).then(d=>{MAP_EXTRAS=d;mapExtrasLoading=false;if(guidePage()==='map')render();else{const host=document.querySelector('#map-pin-detail');if(host&&mapSelected)host.innerHTML=zhHTML(mapPinDetail(mapSelected))}}).catch(()=>{mapExtrasLoading=false;toast('商店与采集资料加载失败，可刷新重试')})};

if(DB)render();

document.addEventListener('change',e=>{if(e.target.matches?.('[data-learning-skill]')){rosterLearningSkill=e.target.value;render()}});

const atlasSelectPin=selectMapPin;
selectMapPin=function(id){atlasSelectPin(id);if(typeof matchMedia==='function'&&matchMedia('(max-width:900px)').matches)document.getElementById('map-pin-detail')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'start'})};
